var index=0;const sdWebData=document.getElementById("sdWebDataID"),spiner=document.getElementById("spinerID"),containerFiles=document.getElementById("containerFilesID"),containerInfo=document.getElementById("containerInfoID"),volumeName=document.getElementById("volumeNameID"),ocupiedSize=document.getElementById("ocupiedSizeID"),totalSpace=document.getElementById("totalSpaceID");function DownloadFile(filename){urlEncodedData=new URLSearchParams,urlEncodedData.append("filename",filename),console.log(urlEncodedData.toString()),fetch("/ftp_get_file",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:urlEncodedData.toString()}).then((response=>{if(response.ok)return response.blob();throw new Error(response.status+" "+response.statusText)})).then((blob=>{const downloadUrl=URL.createObjectURL(blob),a=document.createElement("a");a.href=downloadUrl,a.download=filename,document.body.appendChild(a),a.click(),document.body.removeChild(a),URL.revokeObjectURL(downloadUrl)})).catch((error=>{spiner.style.display="none",sdWebData.className="bd bd-dg",sdWebData.innerHTML=error}))}document.addEventListener("DOMContentLoaded",(()=>{urlEncodedData=new URLSearchParams,urlEncodedData.append("index",index),fetch("/ftp_get_data",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:urlEncodedData.toString()}).then((response=>{if(response.ok)return response.text();throw new Error(response.status+" "+response.statusText)})).then((data=>{spiner.style.display="none",sdWebData.innerHTML="",containerInfo.style.display="block",containerFiles.style.display="block";const params=new URLSearchParams(data),vname=params.get("vname"),freesize=parseInt(params.get("freesize")),totalsize=parseInt(params.get("totalsize")),occupiedSize=totalsize-freesize;totalSpace.innerHTML=totalsize,ocupiedSize.innerHTML=occupiedSize,volumeName.innerHTML=vname;const filenames=params.getAll("filename"),filesizes=params.getAll("filesize");filenames.forEach(((filename,index)=>{const filesize=filesizes[index],fileDiv=document.createElement("div");fileDiv.className="m-1",fileDiv.innerHTML=`\n            <div class="r">\n                <div class="cl cl-nw">${filename}</div>\n                <div class="cl cl-nw">${filesize} bytes</div>\n                <div class="cl cl-nw">\n                    <div class="r j-c">\n                        <div class="btn btn-ss btn-i" onclick="DownloadFile('${filename}')">\n                            <i>&#8595;</i>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        `,containerFiles.appendChild(fileDiv)}))})).catch((error=>{spiner.style.display="none",sdWebData.className="bd bd-dg",sdWebData.innerHTML=error}))}));